def test_parse_positive_int_type_error_single_quotes():
    with patch('sys.stdout', new_callable=lambda: None):
        with patch('sys.stderr', new_callable=lambda: None):
            try:
                parse_positive_int(123)
            except TypeError as e:
                assert str(e) == "text must be a string"
            else:
                assert False, "Expected TypeError"

