def test_parse_positive_int_value_error_negative():
    with patch('sys.stdout', new_callable=lambda: None):
        with patch('sys.stderr', new_callable=lambda: None):
            try:
                parse_positive_int("-5")
            except ValueError as e:
                assert "expected a positive integer, got -5" in str(e)
            else:
                assert False, "Expected ValueError"

